use vstd::prelude::*;

verus! {

spec fn is_odd(x: int) -> bool {
    x % 2 != 0
}

fn find_first_odd(a: &[i32]) -> (found: bool, idx: usize)
    ensures
        // If we say we found one, idx is in-bounds, a[idx] is odd,
        // and all earlier elements are not odd (i.e., idx is the first odd).
        found ==> (
            idx < a.len()
            && is_odd(a[idx] as int)
            && forall|j: int| 0 <= j < idx as int ==> !is_odd(a[j] as int)
        ),
        // If we say we didn't find one, then no element is odd, and we return 0.
        !found ==> (
            idx == 0
            && forall|j: int| 0 <= j < a.len() as int ==> !is_odd(a[j] as int)
        ),
{
    for (i, &x) in a.iter().enumerate()
        invariant
            // i is always a valid "prefix length" into the slice
            i <= a.len(),
            // All elements seen so far are not odd (otherwise we'd have returned)
            forall|j: int| 0 <= j < i as int ==> !is_odd(a[j] as int),
        decreases a.len() - i,
    {
        if x % 2 != 0 {
            // establish postcondition for the early return
            assert(i < a.len());
            assert(is_odd(a[i] as int));
            assert(forall|j: int| 0 <= j < i as int ==> !is_odd(a[j] as int));
            return (true, i);
        }
    }

    // establish postcondition for the "not found" case
    assert(forall|j: int| 0 <= j < a.len() as int ==> !is_odd(a[j] as int));
    (false, 0)
}

} // verus!

